mapper.select:
SELECT rp.id, rp.reporter_id, rp.target_type, rp.target_id, rp.reason, rp.description, rp.status, rp.handler_id, rp.handle_note, rp.handled_at, rp.created_at, u.nickname AS reporter_name, h.nickname AS handler_name, CASE rp.target_type WHEN 'RESOURCE' THEN (SELECT title FROM resource WHERE id = rp.target_id) WHEN 'COMMENT' THEN (SELECT LEFT(content, 50) FROM comment WHERE id = rp.target_id) WHEN 'USER' THEN (SELECT nickname FROM sys_user WHERE id = rp.target_id) ELSE '' END AS target_title FROM report rp LEFT JOIN sys_user u ON u.id = rp.reporter_id LEFT JOIN sys_user h ON h.id = rp.handler_id
rp.status = #{status}
ORDER BY rp.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM report
WHERE reporter_id = #{reporterId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 'PENDING'
